package orchestrator

import (
	"testing"
	"time"
)

// TestBudgetEviction is the acceptance test for spec "Budget-capped
// artifacts": disk truth (orphans included) over the default-cap arithmetic,
// LRU-by-watch-recency order, orphan-first reaping, the `0` = off knob, and
// the within-budget no-op. Each case asserts the exact eviction order.
func TestBudgetEviction(t *testing.T) {
	gb := int64(1) << 30
	mid := time.Date(2026, 10, 1, 0, 0, 0, 0, time.UTC)
	old := time.Date(2026, 9, 1, 0, 0, 0, 0, time.UTC)
	recent := time.Date(2026, 10, 8, 0, 0, 0, 0, time.UTC)

	// watched maps item ids to their playback-progress recency; an item
	// absent from it was never watched (and a dir whose item is gone is an
	// orphan: Live=false).
	library := func(dirs ...ArtifactDir) []ArtifactDir { return dirs }

	cases := []struct {
		name        string
		dirs        []ArtifactDir
		watched     map[string]time.Time
		fronted     map[string]bool
		budgetBytes int64
		want        []string // nil asserts NO evictions
	}{
		{
			name: "within_budget_evicts_nothing",
			dirs: library(
				ArtifactDir{Path: "/r/a/n1", ItemID: "a", Bytes: 4 * gb, Live: true},
			),
			watched:     map[string]time.Time{"a": recent},
			budgetBytes: 32 * gb,
		},
		{
			name:        "zero_budget_disables_the_cap",
			dirs:        library(ArtifactDir{Path: "/r/a/n1", ItemID: "a", Bytes: 40 * gb, Live: true}),
			watched:     map[string]time.Time{"a": recent},
			budgetBytes: 0,
		},
		{
			name:        "negative_budget_reads_as_off",
			dirs:        library(ArtifactDir{Path: "/r/a/n1", ItemID: "a", Bytes: 40 * gb, Live: true}),
			watched:     map[string]time.Time{"a": recent},
			budgetBytes: -1,
		},
		{
			name: "over_budget_reaps_least_recently_watched_first",
			dirs: library(
				ArtifactDir{Path: "/r/a/n1", ItemID: "a", Bytes: 20 * gb, Live: true},
				ArtifactDir{Path: "/r/b/n1", ItemID: "b", Bytes: 20 * gb, Live: true},
			),
			watched:     map[string]time.Time{"a": recent, "b": mid},
			budgetBytes: 32 * gb,
			want:        []string{"/r/b/n1"}, // b older by watch recency
		},
		{
			name: "orphan_and_never_watched_sort_before_watched",
			dirs: library(
				ArtifactDir{Path: "/r/a/n1", ItemID: "a", Bytes: 20 * gb, Live: true},
				ArtifactDir{Path: "/r/dead/n1", ItemID: "dead", Bytes: 20 * gb, Live: false},
			),
			watched:     map[string]time.Time{"a": mid},
			budgetBytes: 32 * gb,
			want:        []string{"/r/dead/n1"}, // orphan is pure waste: first, and reaping it lands within budget
		},
		{
			// Spec scenario: over budget with an orphaned dir AND an
			// oldest-by-watch-recency item — both go, accounting lands
			// within budget, the recently watched artifact stays.
			name: "orphan_plus_stale_watched_reaped_recent_kept",
			dirs: library(
				ArtifactDir{Path: "/r/a/n1", ItemID: "a", Bytes: 20 * gb, Live: true},
				ArtifactDir{Path: "/r/b/n1", ItemID: "b", Bytes: 10 * gb, Live: true},
				ArtifactDir{Path: "/r/c/n1", ItemID: "c", Bytes: 10 * gb, Live: true},
				ArtifactDir{Path: "/r/gone/n1", ItemID: "gone", Bytes: 4 * gb, Live: false},
			),
			watched:     map[string]time.Time{"a": old, "b": recent, "c": recent},
			budgetBytes: 32 * gb,
			want:        []string{"/r/gone/n1", "/r/a/n1"},
		},
		{
			name: "eviction_stops_once_within_budget",
			dirs: library(
				ArtifactDir{Path: "/r/a/n1", ItemID: "a", Bytes: 30 * gb, Live: true},
				ArtifactDir{Path: "/r/b/n1", ItemID: "b", Bytes: 30 * gb, Live: true},
			),
			watched:     map[string]time.Time{"a": old, "b": recent},
			budgetBytes: 32 * gb,
			want:        []string{"/r/a/n1"},
		},
		{
			name: "equal_recency_deterministic_by_path",
			dirs: library(
				ArtifactDir{Path: "/r/b/n1", ItemID: "b", Bytes: 20 * gb, Live: true},
				ArtifactDir{Path: "/r/a/n1", ItemID: "a", Bytes: 20 * gb, Live: true},
			),
			watched:     map[string]time.Time{"a": mid, "b": mid},
			budgetBytes: 32 * gb,
			want:        []string{"/r/a/n1"},
		},
		{
			// The churn break: a fronted build is never-watched by
			// construction (a pilot, next-after-watched) — under a plain
			// recency order it would ALWAYS be the victim while the
			// frontier keeps repacking it. The pin evicts the stale
			// watched artifact first, fronted last.
			name: "fronted_never_watched_outlives_stale_watched",
			dirs: library(
				ArtifactDir{Path: "/r/front/n1", ItemID: "front", Bytes: 20 * gb, Live: true},
				ArtifactDir{Path: "/r/stale/n1", ItemID: "stale", Bytes: 20 * gb, Live: true},
			),
			watched:     map[string]time.Time{"stale": mid}, // front never watched
			fronted:     map[string]bool{"front": true},
			budgetBytes: 32 * gb,
			want:        []string{"/r/stale/n1"},
		},
		{
			// Orphans are still waste-first even with a frontier present:
			// reaping the orphan alone lands within budget, the pinned
			// build stays, nothing live is touched.
			name: "fronted_pin_does_not_shield_orphans",
			dirs: library(
				ArtifactDir{Path: "/r/front/n1", ItemID: "front", Bytes: 20 * gb, Live: true},
				ArtifactDir{Path: "/r/dead/n1", ItemID: "dead", Bytes: 4 * gb, Live: false},
			),
			watched:     map[string]time.Time{},
			fronted:     map[string]bool{"front": true},
			budgetBytes: 22 * gb, // over budget (24) — reaping the orphan lands within it
			want:        []string{"/r/dead/n1"},
		},
		{
			// Budget below the working set: fronted items DO fall to
			// eviction — last, in their own recency order — so the cap
			// still bounds the disk. The caller warns in this case.
			name: "fronted_falls_last_when_budget_unreachable",
			dirs: library(
				ArtifactDir{Path: "/r/f1/n1", ItemID: "f1", Bytes: 20 * gb, Live: true},
				ArtifactDir{Path: "/r/f2/n1", ItemID: "f2", Bytes: 20 * gb, Live: true},
				ArtifactDir{Path: "/r/old/n1", ItemID: "old", Bytes: 20 * gb, Live: true},
			),
			watched:     map[string]time.Time{"old": mid},
			fronted:     map[string]bool{"f1": true, "f2": true},
			budgetBytes: 32 * gb,
			want:        []string{"/r/old/n1", "/r/f1/n1"}, // non-fronted first, then fronted by path
		},
	}
	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			got := Evictions(tc.dirs, tc.watched, tc.fronted, tc.budgetBytes)
			if len(got) != len(tc.want) {
				t.Fatalf("Evictions() = %v, want %v", got, tc.want)
			}
			for i := range got {
				if got[i] != tc.want[i] {
					t.Fatalf("Evictions() = %v, want %v", got, tc.want)
				}
			}
		})
	}
}

// TestEvictionsNeverNil pins the empty-set contract callers iterate over:
// an off cap and an empty artifact root both yield an empty (never nil)
// result... except the off knob, which short-circuits nil by contract.
func TestEvictionsEmptyRoot(t *testing.T) {
	if got := Evictions(nil, nil, nil, 32<<30); len(got) != 0 {
		t.Fatalf("Evictions(nil) = %v, want empty", got)
	}
	if got := Evictions(nil, nil, nil, 0); got != nil {
		t.Fatalf("Evictions(nil, budget 0) = %v, want nil", got)
	}
}
